-- 0562: sample stavans, videos, podcasts and recipes for the JSH sandbox (owner request, 2026-10-01).
--
-- The media library (0560) starts empty, so the new 3L screens in the member app, the Recipe and Podcast
-- shortcuts on Home and My playlist have nothing to show on the sandbox. This adds 25 published samples
-- so they can be tried: 8 stavans, 6 videos, 4 podcast episodes and 7 recipes.
--
--   Stavans and videos   are LINKS to recordings on YouTube, each from the label's, sangh's or institution's own
--                        channel (checked with YouTube's oEmbed on 2026-10-01). Nothing is copied or hosted here, and no
--                        lyrics are stored. They open in the player or the browser; the in-app audio queue plays only
--                        direct audio files, so a YouTube stavan shows "Watch" and is skipped by "Play my playlist".
--   Podcast episodes     are direct https .mp3 enclosures of three real shows' own feeds (Jainism for Everyone, Engaged
--                        Jain Studies Podcast), so they play in the in-app player.
--   Recipes              are written in our own words; every one is flagged fully Jain (no root vegetables, onion, garlic,
--                        mushrooms, yeast or overnight ferments) and was checked by an independent reviewer for that and
--                        for the method; the Random recipe shortcut picks from these.
--
-- Every row carries metadata.sample = true, so all of it can be found (and removed) with one statement:
--   delete from app.content_items where center_id = <the sandbox> and metadata->>'sample' = 'true';
--
-- Safety: app.seed_jsh_sample_media does nothing for an organization that is not a sandbox, adds nothing twice
-- (same community + kind + slug), and is NOT called from seed.sql (local and test databases keep JSH as a
-- production organization, as 0511 explains). This migration runs it once, for JSH, only while JSH is a sandbox.
set client_min_messages = warning;

create or replace function app.seed_jsh_sample_media(p_center uuid) returns jsonb
language plpgsql security definer set search_path = app, public, extensions as $$
declare
  v_env text; r jsonb; v_id uuid; v_added int := 0; v_total int := 0;
begin
  select environment into v_env from app.centers where id = p_center;
  if v_env is null then return jsonb_build_object('added', 0, 'skipped', 'no such organization'); end if;
  if v_env <> 'sandbox' then return jsonb_build_object('added', 0, 'skipped', 'not a sandbox'); end if;
  perform app.set_audit_context('JSH sandbox sample content: stavans, videos, podcasts, recipes (owner request, 2026-10-01)');
  for r in select * from jsonb_array_elements($seed$[{"kind":"stavan","slug":"namokaar-mantra-hai-nyaara-navkar-mantra-bhajan","title":"Namokaar Mantra Hai Nyaara (Navkar Mantra bhajan)","language":"pra","tradition":null,"body_md":null,"media_url":"https://www.youtube.com/watch?v=N3bClpLbOIE","metadata":{"sample":true,"source":"youtube","youtube_id":"N3bClpLbOIE","artist":"Lata Mangeshkar","duration_seconds":1428,"aliases":["Navkar Mantra","Namokaar Mantra Hai Nyaara","Namokar Mantra","Namokar Mahamantra","Navkar Mahamantra","Namaskar Mantra","Namokaar Mantra","Navkaar Mantra","Namo Arihantanam","Panch Parmeshthi Namaskar"],"tags":["mantra","navkar","panch-parmeshthi","daily","jaap","paryushan"],"channel":"Lata Mangeshkar - Topic"}},{"kind":"stavan","slug":"uvasaggaharam-stotra","title":"Uvasaggaharam Stotra","language":"pra","tradition":"shvetambar_murtipujak","body_md":null,"media_url":"https://www.youtube.com/watch?v=aTdxACaUb-A","metadata":{"sample":true,"source":"youtube","youtube_id":"aTdxACaUb-A","artist":"Shrimad Rajchandra Mission Dharampur","duration_seconds":276,"aliases":["Uvasaggaharam","Uvasaggaharam Stotram","Uvasagharam Stotra","Uvasagaharam","Upsargahar Stotra","Upasargahara Stotra"],"tags":["stotra","parshvanath","protection","daily","recitation"],"channel":"Shrimad Rajchandra Mission Dharampur","composer":"Acharya Bhadrabahu (traditional attribution)"}},{"kind":"stavan","slug":"bhaktamar-stotra","title":"Bhaktamar Stotra","language":"sa","tradition":null,"body_md":null,"media_url":"https://www.youtube.com/watch?v=n7k2hhbSCCg","metadata":{"sample":true,"source":"youtube","youtube_id":"n7k2hhbSCCg","artist":"Shrimad Rajchandra Mission Dharampur","duration_seconds":1378,"aliases":["Bhaktamara Stotra","Bhaktamar Stotram","Bhaktamar","Bhaktamber Stotra","Adinath Stotra"],"tags":["stotra","rushabhdev","adinath","sanskrit","48-verses","paryushan"],"channel":"Shrimad Rajchandra Mission Dharampur","composer":"Acharya Manatunga"}},{"kind":"stavan","slug":"jay-jay-aarti-adi-jinanda","title":"Jay Jay Aarti Adi Jinanda","language":"gu","tradition":"shvetambar_murtipujak","body_md":null,"media_url":"https://www.youtube.com/watch?v=2OG6cHgU238","metadata":{"sample":true,"source":"youtube","youtube_id":"2OG6cHgU238","artist":"Shriram Iyer","duration_seconds":366,"aliases":["Jai Jai Aarti Adi Jinanda","Jay Jay Aarti Aadi Jinanda","Jai Jai Aarti Aadijinanda","Jain Aarti","Adinath Aarti"],"tags":["aarti","rushabhdev","adinath","evening","temple"],"channel":"Jain Stavan - Trishla"}},{"kind":"stavan","slug":"mangal-divo","title":"Mangal Divo","language":"gu","tradition":"shvetambar_murtipujak","body_md":null,"media_url":"https://www.youtube.com/watch?v=w0LFgnDRnYM","metadata":{"sample":true,"source":"youtube","youtube_id":"w0LFgnDRnYM","artist":"Mahek Jain and Mallika Jain","duration_seconds":248,"aliases":["Mangal Deevo","Mangal Diva","Manglik Divo","Mangal Divo Aarti","Divo Re Divo"],"tags":["aarti","mangal-divo","evening","temple","diwali"],"channel":"Time Audio Bhakti"}},{"kind":"stavan","slug":"laghu-shanti-stotra","title":"Laghu Shanti Stotra","language":"sa","tradition":"shvetambar_murtipujak","body_md":null,"media_url":"https://www.youtube.com/watch?v=4bKr5_kEjz0","metadata":{"sample":true,"source":"youtube","youtube_id":"4bKr5_kEjz0","artist":"Chhaya Jain","duration_seconds":487,"aliases":["Laghu Shanti","Laghu Shanti Stav","Laghu Shanti Stavan","Laghu Shanti Mantra","Laghu Shanti Sutra"],"tags":["stotra","shantinath","peace","pratikraman","healing"],"channel":"Time Audio Bhakti","composer":"Acharya Manadeva Suri"}},{"kind":"stavan","slug":"taar-ho-taar-prabhu","title":"Taar Ho Taar Prabhu","language":"gu","tradition":"shvetambar_murtipujak","body_md":null,"media_url":"https://www.youtube.com/watch?v=Vh2ECdk91w8","metadata":{"sample":true,"source":"youtube","youtube_id":"Vh2ECdk91w8","artist":"Shrimad Rajchandra Mission Dharampur","duration_seconds":876,"aliases":["Tar Ho Tar Prabhu","Taar Ho Taar Prabhu Stavan","Mahavir Swami Stavan (Devchandraji)","Shri Mahavira Stavan"],"tags":["stavan","mahavir","chovisi","bhakti"],"channel":"Shrimad Rajchandra Mission Dharampur","composer":"Shrimad Devchandraji"}},{"kind":"stavan","slug":"meri-bhavna","title":"Meri Bhavna","language":"hi","tradition":"digambar","body_md":null,"media_url":"https://www.youtube.com/watch?v=D3MmfSS12Gw","metadata":{"sample":true,"source":"youtube","youtube_id":"D3MmfSS12Gw","artist":"Rajshri Soul","duration_seconds":768,"aliases":["Meri Bhawna","Meri Bhaavna","Meri Bhavana"],"tags":["prarthana","bhavna","daily","hindi","digambar"],"channel":"Rajshri Soul","composer":"Pandit Jugal Kishore Mukhtar 'Yugveer'"}},{"kind":"video","slug":"what-is-jainism-jainism-101","title":"What is Jainism? (Jainism 101)","language":"en","tradition":null,"body_md":"A short animated primer on the origin and basic ideas of Jainism, from the soul to non-violence and vegetarianism. The first video in Young Jains of America's Jainism 101 series, a good first watch for new members and older children.","media_url":"https://www.youtube.com/watch?v=sv6goJoB8XQ","metadata":{"sample":true,"source":"youtube","youtube_id":"sv6goJoB8XQ","artist":"Young Jains of America","duration_seconds":90,"tags":["introduction","core principles","ahimsa","jainism 101","youth"],"channel":"Young Jains of America"}},{"kind":"video","slug":"paryushan-and-das-lakshan-jainism-101","title":"Paryushan and Das Lakshan (Jainism 101)","language":"en","tradition":null,"body_md":"A quick overview of Paryushan and Das Lakshan: what the two festivals mean and how families observe them. It covers both the Shvetambar and Digambar observances side by side, which suits a community that has both.","media_url":"https://www.youtube.com/watch?v=n6ZFohBo7No","metadata":{"sample":true,"source":"youtube","youtube_id":"n6ZFohBo7No","artist":"Young Jains of America","duration_seconds":76,"tags":["festival","paryushan","das lakshan","forgiveness","shvetambar","digambar"],"channel":"Young Jains of America"}},{"kind":"video","slug":"ranakpur-s-chaturmukh-jain-temple","title":"Ranakpur's Chaturmukh Jain Temple","language":"en","tradition":null,"body_md":"A short documentary segment on the 500-year-old marble temple at Ranakpur, dedicated to Bhagwan Adinath: its carving, the Kalpavriksha and the story of the one pillar that is not straight. Made by a documentary network, it looks at the architecture rather than the worship.","media_url":"https://www.youtube.com/watch?v=BPbv72G9y4A","metadata":{"sample":true,"source":"youtube","youtube_id":"BPbv72G9y4A","artist":"HISTORY TV18","duration_seconds":196,"tags":["temple","tirth","ranakpur","adinath","architecture","darshan"],"channel":"HISTORY TV18"}},{"kind":"video","slug":"jainism-and-ecology-with-christopher-key-chapple","title":"Jainism and Ecology with Christopher Key Chapple","language":"en","tradition":null,"body_md":"Christopher Key Chapple, a scholar of Jainism, talks with Mary Evelyn Tucker about Jain cosmology and karma, diet and non-violence, environmental ethics and ahimsa in social action. A ten-minute talk for teens and adults.","media_url":"https://www.youtube.com/watch?v=3vXcp69wYrg","metadata":{"sample":true,"source":"youtube","youtube_id":"3vXcp69wYrg","artist":"Christopher Key Chapple","duration_seconds":634,"tags":["talk","scholar","ahimsa","aparigraha","ecology","environment"],"channel":"Yale Forum on Religion and Ecology"}},{"kind":"video","slug":"raja-shrenik-and-the-frog-animated-story","title":"Raja Shrenik and the Frog (animated story)","language":"en","tradition":null,"body_md":"An animated pathshala-style retelling of the story of the little frog that sets out to see Bhagwan Mahavir, alongside King Shrenik. It is about sincere devotion. The story is taught in both Shvetambar and Digambar pathshalas.","media_url":"https://www.youtube.com/watch?v=9qrWhISftwI","metadata":{"sample":true,"source":"youtube","youtube_id":"9qrWhISftwI","artist":"Jain Pathshala English","duration_seconds":255,"tags":["children","story","pathshala","animated","bhakti","mahavir"],"channel":"Jain Pathshala English"}},{"kind":"video","slug":"why-jains-avoid-root-vegetables","title":"Why Jains avoid root vegetables","language":"hi","tradition":null,"body_md":"A Hindi explainer on why Jain practice avoids potatoes, onions, garlic, carrots and other root vegetables (kandmool), tied back to ahimsa. From the Jain Media channel, which also has a written article on the topic.","media_url":"https://www.youtube.com/watch?v=mZIdoNvzgsU","metadata":{"sample":true,"source":"youtube","youtube_id":"mZIdoNvzgsU","artist":"Jain Media","duration_seconds":833,"tags":["food","practice","kandmool","root vegetables","ahimsa","ahar"],"channel":"Jain Media"}},{"kind":"podcast","slug":"jainism-for-everyone-discussion-142-the-24-tirthankars","title":"The 24 Tirthankars","language":"en","tradition":null,"body_md":"Episode 142 of the Jainism for Everyone podcast, hosted by Timir Chheda: a discussion of the 24 Tirthankars. About 54 minutes.","media_url":"https://static1.squarespace.com/static/5b7b88d7cef37238032c7583/t/67dc67c09c86405e804df2f2/1742497772717/J4E+Discussion+142+The+24+Tirthankars.mp3","metadata":{"sample":true,"source":"link","artist":"Timir Chheda","series":"Jainism for Everyone","episode":"142","duration_seconds":3226,"tags":["tirthankars","teaching","history","beginners","family"],"episode_page":"https://jainismforeveryone.com/all/2025/3/20/j4e-discussion-142-the-24-tirthankars"}},{"kind":"podcast","slug":"jainism-for-everyone-discussion-143-three-stories-about-mahavir","title":"Three Stories about Mahavir","language":"en","tradition":null,"body_md":"Episode 143 of the Jainism for Everyone podcast, hosted by Timir Chheda: three stories about Bhagwan Mahavir, released the week after Mahavir Jayanti 2025. About 49 minutes.","media_url":"https://static1.squarespace.com/static/5b7b88d7cef37238032c7583/t/68015afce8e40c4d8d8e4cba/1744919330836/J4E+Discussion+143+Three+Stories+about+Mahavir.mp3","metadata":{"sample":true,"source":"link","artist":"Timir Chheda","series":"Jainism for Everyone","episode":"143","duration_seconds":2915,"tags":["mahavir","stories","mahavir-jayanti","teaching","family"],"episode_page":"https://jainismforeveryone.com/all/2025/4/17/j4e-discussion-143-three-stories-about-mahavir"}},{"kind":"podcast","slug":"engaged-jain-studies-podcast-13-forgiveness-as-compassion","title":"Forgiveness as Compassion","language":"en","tradition":null,"body_md":"Dr. Venu Mehta, a Jain studies scholar from Gujarat, explains kshamapana (forgiveness) as a form of compassion: how Jain texts and customs express it and how to practise it day to day. A good listen around Paryushan and Samvatsari. From the Engaged Jain Studies Podcast.","media_url":"https://podcasts.captivate.fm/media/81bd1981-186c-4ef7-b89f-aa167c818298/ejsp13-1.mp3","metadata":{"sample":true,"source":"link","artist":"Venu Mehta","series":"Engaged Jain Studies Podcast","episode":"13","duration_seconds":2736,"tags":["forgiveness","kshamapana","paryushan","ahimsa","practice"],"episode_page":"https://podcasts.apple.com/us/podcast/venu-mehta-forgiveness-as-compassion/id1747384751?i=1000691620691"}},{"kind":"podcast","slug":"engaged-jain-studies-podcast-12-jain-teachings-practices-of-compassion","title":"Jain Teachings & Practices of Compassion","language":"en","tradition":null,"body_md":"Professor Jeffery Long explains how the Jain worldview leads naturally to compassion, focusing on anekantavada (many perspectives) and aparigraha (non-possession). He gives Acharya Chandanaji's Veerayatan and Acharya Tulsi's Anuvrat movement as examples of these values put into practice.","media_url":"https://podcasts.captivate.fm/media/22554c1d-6e82-4967-ac22-ef8ce2ca8c73/ejsp-12-v2.mp3","metadata":{"sample":true,"source":"link","artist":"Jeffery D. Long","series":"Engaged Jain Studies Podcast","episode":"12","duration_seconds":3990,"tags":["compassion","anekantavada","aparigraha","philosophy","seva"],"episode_page":"https://podcasts.apple.com/us/podcast/jeffery-d-long-jain-teachings-practices-of-compassion/id1747384751?i=1000687009825"}},{"kind":"recipe","slug":"gujarati-kadhi-jain-style","title":"Gujarati Kadhi (Jain style)","language":"en","tradition":null,"body_md":"A thin, gently sweet-and-tangy yogurt soup thickened with chickpea flour and finished with a ghee tempering of whole spices. It is the everyday partner to khichdi and plain rice in Gujarati homes.\n\n## Method\n\nStep 1: In a medium saucepan, whisk the yogurt with 2 cups of the water until completely smooth. This is your buttermilk.\n\nStep 2: In a small bowl, whisk the besan with the remaining 1 cup water until there are no lumps. Set it aside.\n\nStep 3: Put the saucepan of buttermilk over medium heat. Whisk constantly until it is very hot and steaming, with tiny bubbles at the edge, 6 to 8 minutes. Do not walk away; steady stirring keeps it from splitting. A slightly grainy look is fine and will smooth out in the next step.\n\nStep 4: Whisk the besan mixture again, then pour it into the hot buttermilk in a thin stream while whisking.\n\nStep 5: Add the salt, turmeric, sonth and jaggery. Keep whisking until the kadhi comes to a boil, about 3 minutes.\n\nStep 6: Turn the heat to low and simmer for 10 minutes, stirring every minute or two, until it is slightly thicker than milk and no longer tastes of raw flour.\n\nStep 7: For the tempering, warm the ghee in a small pan over medium heat. Add the mustard seeds and wait until they pop. Add the cumin, fenugreek seeds, cloves, cinnamon and red chilies and stir for 15 seconds. Add the hing and turn off the heat.\n\nStep 8: Pour the tempering into the kadhi (stand back, it splutters). Simmer 2 more minutes.\n\nStep 9: Taste and adjust salt and sweetness. Add the lemon juice if you want more tang. Serve hot with khichdi or rice.\n\n## Jain notes\n\nFully Jain: no root vegetables, onion, garlic, fungus, eggs or anything fermented overnight. Traditional kadhi uses a fresh ginger and green chili paste. Here dried ginger powder (sonth) and dried red chilies take their place. Curry leaves and a cilantro garnish are also usual and are left out because they are leafy greens. Dvidal: the buttermilk is heated thoroughly before the besan (a pulse flour) is added, as strict Jain kitchens do. Use yogurt set at home the same day from boiled milk. Do not substitute store-bought yogurt: it is set days or weeks before it is eaten, so it does not meet the same-day rule. Some US cane sugar is filtered through bone char, so jaggery or a certified vegan sugar avoids that. With no fresh vegetables, this kadhi suits tithis; leave out the optional lemon juice on those days, since lemon is fresh produce. It is not Ayambil food, because it contains dairy, ghee and spices.","media_url":null,"metadata":{"sample":true,"fully_jain":true,"ingredients":["1 1/2 cups plain whole-milk yogurt, homemade from boiled milk and set the same day","3 cups water, divided","3 tablespoons besan (chickpea flour)","1/2 teaspoon dried ginger powder (sonth)","1/4 teaspoon ground turmeric","1 1/4 teaspoons salt, or to taste","2 to 3 tablespoons grated jaggery (or sugar), to taste","1 tablespoon ghee","1/2 teaspoon mustard seeds","1/2 teaspoon cumin seeds","1/4 teaspoon fenugreek seeds (methi dana)","3 whole cloves","1 small cinnamon stick (about 1 inch)","2 dried red chilies, broken in half","1/8 teaspoon asafoetida (hing)","1 teaspoon lemon juice (optional, if your yogurt is very mild; leave out on tithis)"],"servings":4,"prep_minutes":5,"cook_minutes":25,"tags":["gujarati","kadhi","yogurt","tithi-friendly","no fresh vegetables","pairs with khichdi"]}},{"kind":"recipe","slug":"dal-dhokli","title":"Dal Dhokli","language":"en","tradition":null,"body_md":"Spiced wheat-flour diamonds simmered in a sweet, tangy toor dal until the broth turns silky. It is a one-pot Gujarati comfort meal that needs nothing else on the plate.\n\n## Method\n\nStep 1: Rinse the toor dal in 3 changes of water. Put it in a pressure cooker (3 liters or larger) with 2 1/2 cups water and 1/4 teaspoon turmeric. Close the lid with the weight on and cook on medium heat. Each time pressure builds, the weight lifts and lets out a loud hiss of steam; that is one whistle. After the 4th whistle, turn off the heat and leave the cooker closed until the pressure drops on its own, about 10 to 15 minutes, and the lid opens without force. Never force the lid or lift the weight to let steam out. (Instant Pot: high pressure 10 minutes, natural release 10 minutes. No cooker: soak the dal 30 minutes, then simmer covered in a pot with 4 cups water for 40 to 45 minutes until very soft; this takes about 20 minutes longer overall.)\n\nStep 2: While the dal cooks, make the dhokli dough. In a bowl, mix the wheat flour, besan, turmeric, chili powder, salt and oil. Crush the ajwain between your palms and add it. Add water a little at a time and knead into a firm, smooth dough, like rotli dough. Cover and rest 10 minutes.\n\nStep 3: Divide the dough into 3 balls. Dust with flour and roll each into a thin circle about 8 inches across. Cut into 1 1/2-inch diamonds with a knife or pizza cutter. Spread the pieces on a floured plate so they do not stick together.\n\nStep 4: Whisk the cooked dal until smooth and pour it into a wide, heavy pot. Stir in 3 cups hot water, the salt, jaggery, kokum, sonth, chili powder, dhana-jiru and cashews (if using). Bring to a rolling boil over medium-high heat.\n\nStep 5: For the tempering, warm the ghee in a small pan over medium heat. Add the mustard seeds and wait until they pop. Add the cumin, cloves, cinnamon, bay leaf and red chilies and stir for 10 seconds. Add the hing and pour the tempering into the boiling dal right away (careful, it splutters).\n\nStep 6: With the dal at a steady boil, drop in the dhokli pieces a handful at a time, stirring gently after each handful so they do not clump.\n\nStep 7: Simmer uncovered on medium for 12 to 15 minutes, stirring every couple of minutes so nothing sticks to the bottom. The dhokli are done when you cut one open and see no dry flour in the center.\n\nStep 8: The dal thickens as it stands, so add a little hot water if it gets too thick. Taste for salt, sweetness and sourness, and add lemon juice now if you skipped the kokum.\n\nStep 9: Serve hot in bowls with a small spoonful of ghee on top.\n\n## Jain notes\n\nFully Jain: no onion, garlic, fresh ginger or other root vegetables. Dried ginger powder (sonth) gives the warmth fresh ginger would. Many Gujarati homes add peanuts. They are left out here because peanuts form underground, and this app's rule excludes anything grown underground. Cashews are offered instead. Curry leaves and a cilantro garnish are traditional and are omitted because they are leafy greens. Some cooks add a chopped tomato. If you do, families who avoid fresh green produce on tithis will not eat it on those days. As written, with dried kokum and no fresh vegetables, it is tithi-friendly. Make and eat it the same day; do not keep the dough or leftovers overnight. During chomasu, many families use only freshly milled flour.","media_url":null,"metadata":{"sample":true,"fully_jain":true,"ingredients":["3/4 cup toor dal (split pigeon peas)","2 1/2 cups water, for cooking the dal","1/4 teaspoon ground turmeric, for the dal","3 cups hot water, for thinning the dal (plus more as needed)","1 1/2 teaspoons salt, or to taste","2 tablespoons grated jaggery","4 pieces dried kokum, rinsed (or 1 tablespoon lemon juice added at the end)","1/2 teaspoon dried ginger powder (sonth)","1 teaspoon red chili powder (Kashmiri for a milder dish)","1 teaspoon coriander-cumin powder (dhana-jiru)","1/4 cup raw cashew halves (optional)","2 tablespoons ghee, for tempering, plus 1 to 2 teaspoons for serving (optional)","1 teaspoon mustard seeds","1/2 teaspoon cumin seeds","4 whole cloves","1 cinnamon stick (about 1 inch)","1 dried bay leaf (tej patta)","2 dried red chilies","1/4 teaspoon asafoetida (hing)","1 cup whole wheat flour (chapati atta), for the dhokli","2 tablespoons besan (chickpea flour)","1/4 teaspoon ground turmeric, for the dhokli","1/2 teaspoon red chili powder, for the dhokli","1/4 teaspoon ajwain (carom seeds)","1/2 teaspoon salt, for the dhokli","1 tablespoon neutral oil (sunflower or canola)","About 1/3 cup water, for the dough","Extra flour, for rolling"],"servings":4,"prep_minutes":25,"cook_minutes":50,"tags":["gujarati","dal","one-pot","tithi-friendly","no fresh vegetables","comfort food"]}},{"kind":"recipe","slug":"sev-tameta-nu-shaak","title":"Sev Tameta nu Shaak","language":"en","tradition":null,"body_md":"Ripe tomatoes cooked down into a sweet-spicy gravy and topped with crunchy besan sev just before serving. It is a quick weeknight shaak for rotli or bhakri.\n\n## Method\n\nStep 1: Wash the tomatoes and pat them dry. Cut them open, check that they are clean inside, and chop them into small pieces.\n\nStep 2: Heat the oil in a medium pan over medium heat. Add the mustard seeds and wait until they pop. Add the cumin seeds, then the hing and the green chili (if using), and stir for 10 seconds.\n\nStep 3: Add the tomatoes, turmeric and salt. Stir, cover and cook for 5 to 6 minutes, until the tomatoes are soft. Mash them a little with the back of the spoon.\n\nStep 4: Stir in the chili powder, dhana-jiru, sugar and water. Simmer uncovered for 3 to 4 minutes, until you have a loose gravy and a little oil shines at the edges.\n\nStep 5: Wait until you are ready to eat, then turn off the heat and stir in 1 cup of sev. It softens in a minute or two. If you add it earlier, it turns mushy.\n\nStep 6: Spoon into a serving bowl, scatter the remaining sev on top for crunch, and serve right away with rotli, bhakri or puri.\n\n## Jain notes\n\nFully Jain as written: tomatoes, besan sev and dry spices only. Restaurant and Kathiyawadi versions often add onion and garlic. Here hing gives the savory depth instead. A cilantro garnish is traditional and is left out because it is a leafy green. Use homemade sev, or fresh plain besan sev with a label you have checked. Avoid garlic sev or flavored sev. Day-specific caution: tomatoes and green chili are fresh green produce, so families who avoid green vegetables on tithis, during Paryushan or on Ayambil days will not make this dish then.","media_url":null,"metadata":{"sample":true,"fully_jain":true,"ingredients":["4 medium ripe tomatoes (about 1 1/4 pounds)","2 tablespoons neutral oil (sunflower or canola)","1/2 teaspoon mustard seeds","1/2 teaspoon cumin seeds","1/8 teaspoon asafoetida (hing)","1 green chili, finely chopped (optional)","1/4 teaspoon ground turmeric","3/4 teaspoon salt, or to taste","1 teaspoon red chili powder","1 1/2 teaspoons coriander-cumin powder (dhana-jiru)","1 to 2 teaspoons sugar or grated jaggery","1/2 cup water","1 cup thick plain besan sev, plus 1/4 cup for topping"],"servings":4,"prep_minutes":10,"cook_minutes":15,"tags":["gujarati","kathiyawadi","shaak","tomato","quick","weeknight"]}},{"kind":"recipe","slug":"bhinda-nu-shaak-with-roasted-besan","title":"Bhinda nu Shaak with Roasted Besan","language":"en","tradition":null,"body_md":"Tender okra rounds cooked dry in a skillet and coated in toasted chickpea flour and spices for a nutty, non-slimy sabzi. It is a staple beside dal-bhaat-rotli.\n\n## Method\n\nStep 1: Wash the okra and dry every pod completely with a kitchen towel. Spread the pods on a dry towel for 15 minutes. Wet okra turns slimy when cooked.\n\nStep 2: Trim off the tops and tips and cut the pods into 1/2-inch rounds. Look at the cut slices as you go and discard any pod with holes, dark spots or anything living inside.\n\nStep 3: Put the besan in a dry skillet over medium-low heat. Stir constantly for 3 to 4 minutes, until it smells nutty and turns a shade darker. Move it to a small bowl and mix in the chili powder, dhana-jiru and sugar.\n\nStep 4: Wipe out the skillet. Heat the oil over medium heat, add the ajwain (or cumin) and sesame seeds, and when they sizzle add the hing.\n\nStep 5: Add the okra, turmeric and salt and stir gently to coat. Cook uncovered for 10 to 12 minutes, stirring gently every 2 minutes, until the okra is tender and lightly browned at the edges. Do not cover the pan, because trapped steam makes okra slimy.\n\nStep 6: Sprinkle the besan mixture evenly over the okra. Stir gently and cook 3 to 4 minutes more, until the besan coats the pieces and smells roasted.\n\nStep 7: Turn off the heat, toss with the amchur or lemon juice, and serve with rotli and dal.\n\n## Jain notes\n\nFully Jain: okra, besan and dry spices only, with no root vegetables, onion, garlic or fresh ginger. North Indian bhindi masala usually adds onion and garlic, and this recipe does not. Checking each pod as you cut it is part of jiv-daya, the care not to harm small creatures. A cilantro garnish is common and is left out because it is a leafy green. Day-specific caution: okra is a fresh green vegetable, so families who avoid green produce on tithis, during Paryushan or on Ayambil days will skip it then. Cook and eat it the same day.","media_url":null,"metadata":{"sample":true,"fully_jain":true,"ingredients":["1 pound fresh, tender okra (bhinda)","3 tablespoons neutral oil (sunflower or canola)","1/2 teaspoon ajwain (carom seeds) or cumin seeds","1 tablespoon sesame seeds (optional)","1/8 teaspoon asafoetida (hing)","1/4 teaspoon ground turmeric","1 teaspoon salt, or to taste","1/4 cup besan (chickpea flour)","1 teaspoon red chili powder","1 1/2 teaspoons coriander-cumin powder (dhana-jiru)","1 teaspoon sugar","1/2 teaspoon amchur (dry mango powder) or 1 teaspoon lemon juice"],"servings":4,"prep_minutes":25,"cook_minutes":20,"tags":["gujarati","shaak","okra","bhinda","dry sabzi","everyday"]}},{"kind":"recipe","slug":"kacha-kela-nu-shaak-raw-banana-in-place-of-potato","title":"Kacha Kela nu Shaak (Raw Banana in Place of Potato)","language":"en","tradition":null,"body_md":"Cubes of raw green banana stir-fried with ajwain, sesame and Gujarati spices, with the soft centers and golden edges of a dry potato shaak. It is the classic Jain stand-in for batata nu shaak.\n\n## Method\n\nStep 1: Rub a few drops of oil on your hands and knife, because raw banana sap is sticky and stains. Stir 1/4 teaspoon turmeric into 4 cups water in a bowl.\n\nStep 2: Trim both ends of each banana and peel off the thick green skin with a vegetable peeler or a paring knife.\n\nStep 3: Cut each banana lengthwise into quarters, then crosswise into 1/2-inch pieces. Drop them into the turmeric water as you go so they do not darken. Drain well just before cooking.\n\nStep 4: Heat the oil in a wide skillet over medium heat. Add the mustard seeds and wait until they pop. Add the ajwain and sesame seeds, and when they sizzle add the hing.\n\nStep 5: Add the drained banana, turmeric and salt and stir to coat. Sprinkle in 1/4 cup water, cover, and cook on medium-low for 8 to 10 minutes, stirring once or twice. They are ready for the next step when a knife slides in easily, like a boiled potato.\n\nStep 6: Uncover and add the chili powder, dhana-jiru and sugar. Cook uncovered for 3 to 4 minutes, turning the pieces gently, until the edges are golden and the pan is dry.\n\nStep 7: Turn off the heat, stir in the lemon juice or amchur, and serve with rotli, puri or dal-bhaat.\n\n## Jain notes\n\nFully Jain: potato is a root vegetable (kandmool) and is never used, so raw banana takes its place. This is the standard Jain swap, and it works the same way in other potato dishes. No onion, garlic or fresh ginger is used. Some cooks finish it with crushed peanuts, which are left out because this app excludes anything that forms underground; sesame seeds give the crunch instead. Day-specific caution: raw banana is fresh green produce, so families who avoid green vegetables on tithis, during Paryushan or on Ayambil days will not make it then. Cut and cook the bananas on the day you eat them.","media_url":null,"metadata":{"sample":true,"fully_jain":true,"ingredients":["3 medium raw green bananas (kacha kela), about 1 1/2 pounds; sold as raw banana at Indian grocers, or use green plantains","1/4 teaspoon ground turmeric plus 4 cups water, for holding the cut pieces","2 tablespoons neutral oil (sunflower or canola), plus a few drops for your hands","1/2 teaspoon mustard seeds","1/2 teaspoon ajwain (carom seeds)","1 tablespoon sesame seeds","1/8 teaspoon asafoetida (hing)","1/4 teaspoon ground turmeric, for cooking","1 teaspoon salt, or to taste","1/4 cup water, for steaming","1 teaspoon red chili powder","1 1/2 teaspoons coriander-cumin powder (dhana-jiru)","1 1/2 teaspoons sugar","2 teaspoons lemon juice (or 1/2 teaspoon amchur)"],"servings":4,"prep_minutes":15,"cook_minutes":20,"tags":["gujarati","shaak","raw banana","potato substitute","dry sabzi","everyday"]}},{"kind":"recipe","slug":"gujarati-moong-dal-khichdi","title":"Gujarati Moong Dal Khichdi","language":"en","tradition":null,"body_md":"Rice and yellow moong dal cooked soft with ghee and whole spices: light, soothing and ready in about half an hour. Serve it the Gujarati way, with kadhi.\n\n## Method\n\nStep 1: Put the rice and moong dal in a bowl and rinse in 3 changes of water, rubbing gently, until the water is mostly clear. Cover with fresh water and soak for 20 minutes, then drain.\n\nStep 2: Heat 1 tablespoon of the ghee in a pressure cooker or heavy pot over medium heat (Instant Pot: use Sauté mode on normal). Add the cumin, cloves, peppercorns, cinnamon and bay leaf. When the cumin sizzles (about 20 seconds), add the hing.\n\nStep 3: Add the drained rice and dal and stir gently for 1 minute so the grains are coated in ghee.\n\nStep 4: Add the 4 cups water, turmeric and salt and stir. Scrape the bottom well so nothing is stuck (in an Instant Pot this prevents the Burn warning). Instant Pot: press Cancel to turn off Sauté before sealing.\n\nStep 5: Pressure cooker (3 liters or larger, so it is no more than half full, because dal and rice foam): close the lid with the weight on and cook on medium heat. Each time pressure builds, the weight lifts and lets out a loud hiss of steam; that is one whistle. After the 3rd whistle, turn off the heat and leave it closed until the pressure drops on its own and the lid opens without force, about 10 minutes. Never force the lid or lift the weight to let steam out. Instant Pot: high pressure for 8 minutes, then natural release for 10 minutes. Regular pot: bring to a boil, cover, and cook on low for 25 to 30 minutes, stirring now and then and adding a splash of hot water if it looks dry.\n\nStep 6: Open the lid and stir well, mashing lightly with the back of the spoon for a creamy texture. If it is thicker than you like, stir in a little hot water.\n\nStep 7: Serve hot with the remaining ghee spooned on top, alongside kadhi.\n\n## Jain notes\n\nFully Jain: rice, moong dal, ghee and dry spices only. Some khichdi recipes add potato, carrot, onion or fresh ginger. None are used here. If you want vegetables, add green peas or corn, which are allowed, but note they make the dish unsuitable for families who avoid fresh green produce on tithis. As written, it is tithi-friendly. Dvidal: moong is a pulse. If you serve khichdi with chaas (buttermilk) or plain yogurt instead of kadhi, use yogurt set at home the same day from boiled milk (not store-bought), and strict families heat it before it meets the dal. Cooked kadhi needs no change. Eat it the same day and do not keep leftovers overnight. It is not Ayambil food, which leaves out ghee and most spices.","media_url":null,"metadata":{"sample":true,"fully_jain":true,"ingredients":["3/4 cup rice (sona masoori or any short- to medium-grain rice)","1/2 cup yellow moong dal (split, skinned mung beans)","4 cups water","1/2 teaspoon ground turmeric","1 teaspoon salt, or to taste","2 tablespoons ghee, divided","1 teaspoon cumin seeds","3 whole cloves","4 black peppercorns","1 small cinnamon stick (about 1 inch)","1 dried bay leaf (tej patta)","1/8 teaspoon asafoetida (hing)"],"servings":4,"prep_minutes":25,"cook_minutes":25,"tags":["gujarati","khichdi","rice","dal","tithi-friendly","no fresh vegetables","pairs with kadhi"]}},{"kind":"recipe","slug":"sukhdi-gol-papdi","title":"Sukhdi (Gol Papdi)","language":"en","tradition":null,"body_md":"Whole wheat flour roasted slowly in ghee until nutty, then bound with melted jaggery and cut into squares that keep well. It is a three-ingredient Gujarati sweet for prasad, travel and Paryushan visits.\n\n## Method\n\nStep 1: Grease an 8-inch square pan or a steel thali with ghee. Keep it beside the stove, along with a flat-bottomed cup or bowl for pressing.\n\nStep 2: Melt the 1/2 cup ghee in a heavy-bottomed pan or kadai over medium-low heat.\n\nStep 3: Add the flour and stir constantly, breaking up any lumps. Roast for 10 to 12 minutes, until it turns golden brown, smells nutty, and loosens into a frothy, bubbling mixture. Keep the heat low so it does not burn.\n\nStep 4: Turn off the heat and let the pan sit for 30 to 60 seconds. If it is too hot when the jaggery goes in, the jaggery caramelizes and the sukhdi sets rock-hard. If it is too cool, the jaggery will not melt.\n\nStep 5: Add the jaggery and cardamom and stir quickly until the jaggery has fully melted and the mixture looks smooth and glossy, about 1 minute.\n\nStep 6: Pour it at once into the greased pan. Spread it out and press it flat with the bottom of the cup to about 1/2 inch thick. Scatter the nuts over the top and press them in lightly.\n\nStep 7: After about 5 minutes, while it is still warm, cut it into squares or diamonds with a knife. Let it cool completely (about 20 minutes) before lifting out the pieces.\n\nStep 8: Store in an airtight container at room temperature.\n\n## Jain notes\n\nFully Jain: wheat flour, ghee and jaggery, with no honey, gelatin, eggs or anything fermented. It uses no fresh produce, so it suits tithis and many families make it during Paryushan. Nuts are optional, because some families avoid certain dried fruits and nuts during chomasu. Follow your family's shelf-life limits (kaal maryada) for flour-and-ghee sweets. Commonly cited limits are about 15 days in chomasu, 20 in summer and 30 in winter, and many families keep it for much less. It is not Ayambil food, which excludes ghee and sweets.","media_url":null,"metadata":{"sample":true,"fully_jain":true,"ingredients":["1 cup whole wheat flour (coarse atta works best)","1/2 cup ghee, plus 1 teaspoon for greasing","1/2 to 2/3 cup grated or finely chopped jaggery, packed (soft jaggery melts most easily)","1/2 teaspoon ground cardamom (optional)","1 tablespoon sliced almonds or chopped pistachios (optional)"],"servings":8,"prep_minutes":5,"cook_minutes":15,"tags":["gujarati","sweet","mithai","jaggery","prasad","tithi-friendly","paryushan-friendly","travel food"]}}]$seed$::jsonb) loop
    v_total := v_total + 1;
    v_id := null;
    insert into app.content_items (center_id, tradition, kind, slug, title, body_md, language, media_url, metadata, status, published_at)
    select p_center, nullif(r->>'tradition', '')::app.tradition, r->>'kind', r->>'slug', r->>'title', r->>'body_md',
           coalesce(r->>'language', 'en'), r->>'media_url', coalesce(r->'metadata', '{}'::jsonb), 'published', now()
     where not exists (select 1 from app.content_items c where c.center_id = p_center and c.kind = r->>'kind' and c.slug = r->>'slug')
    returning id into v_id;
    if v_id is not null then v_added := v_added + 1; end if;
  end loop;
  return jsonb_build_object('added', v_added, 'already_there', v_total - v_added);
end $$;
comment on function app.seed_jsh_sample_media(uuid) is
  'Sample stavans, videos, podcasts and recipes for a SANDBOX organization (0562). Idempotent; refuses anything that is not a sandbox. Rows carry metadata.sample = true.';
revoke execute on function app.seed_jsh_sample_media(uuid) from public, anon, authenticated;
grant execute on function app.seed_jsh_sample_media(uuid) to service_role;

do $$ declare r jsonb; begin
  select app.seed_jsh_sample_media(id) into r from app.centers where slug = 'jsh' and environment = 'sandbox';
  raise warning '0562 sample media for the JSH sandbox: %', coalesce(r::text, 'JSH is not a sandbox (or does not exist) - nothing added');
end $$;
